[Property("Category", "RMQ")]
[NotInParallel("Quorum")]
public class WhenRequeuingAFailedMessageWithZeroDelayShouldRedeliverImmediately : IDisposable
{
    private readonly IAmAMessageGatewayReactorProvider _messageGatewayProvider;
    private readonly IAmAMessageBuilder _messageBuilder;
    private readonly IAmAMessageAssertion _messageAssertion;

    private List<Message> _sentMessages = [];

    private Paramore.Brighter.MessagingGateway.RMQ.Async.RmqSubscription? _subscription;
    private Paramore.Brighter.MessagingGateway.RMQ.Async.RmqPublication? _publication;

    private IAmAMessageProducerSync? _producer = null;
    private IAmAChannelSync? _channel = null;

    public WhenRequeuingAFailedMessageWithZeroDelayShouldRedeliverImmediately()
    {
        _messageGatewayProvider = new Paramore.Brighter.RMQ.Async.Tests.MessagingGateway.RmqQuorumMessageGatewayProvider();
        _messageBuilder = new DefaultMessageBuilder();
        _messageAssertion = new RmqMessageAssertion();
    }

    public void Dispose()
    {
        _messageGatewayProvider.CleanUp(_producer, _channel, _sentMessages);
    }

    [Test]

    public async Task When_requeuing_a_failed_message_with_zero_delay_should_redeliver_immediately()
    {
        // Arrange
        _publication = _messageGatewayProvider.CreatePublication(_messageGatewayProvider.GetOrCreateRoutingKey());
        _subscription = _messageGatewayProvider.CreateSubscription(_publication.Topic!,
            _messageGatewayProvider.GetOrCreateChannelName(),
            OnMissingChannel.Create);

        _producer = _messageGatewayProvider.CreateProducer(_publication);
        _channel = _messageGatewayProvider.CreateChannel(_subscription);

        var message = _messageBuilder.SetTopic(_publication.Topic!).Build();
        _sentMessages.Add(message);

        _producer.Send(message);

        // Act — receive the message and requeue it with an explicit TimeSpan.Zero
        var received = _channel.Receive(TimeSpan.FromMilliseconds(4000));
        await Assert.That(received.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);

        var requeued = _channel.Requeue(received, TimeSpan.Zero);
        await Assert.That(requeued).IsTrue();

        // The window opens when Requeue RETURNS. The call's own duration is a round trip to the
        // broker to issue the instruction — the cost of asking, not a delay applied to the
        // message — so charging it to the budget would measure network latency rather than the
        // gateway's treatment of TimeSpan.Zero.
        var stopwatch = Stopwatch.StartNew();

        // Assert — poll every 500 ms, giving up after 30 s. TimeSpan.Zero must not be
        // special-cased: the message arrives on the first iteration, and the time from the
        // Requeue call returning to receipt must be less than 5 s.
        var redelivered = new Message();
        while (stopwatch.Elapsed < TimeSpan.FromSeconds(30))
        {
            redelivered = _channel.Receive(TimeSpan.FromMilliseconds(500));
            if (redelivered.Header.MessageType != MessageType.MT_NONE)
            {
                break;
            }
        }

        await Assert.That(redelivered.Header.MessageType).IsNotEqualTo(MessageType.MT_NONE);
        await Assert.That(stopwatch.Elapsed < TimeSpan.FromSeconds(5)).IsTrue().Because($"Expected redelivery within 5 s of Requeue(M, TimeSpan.Zero) returning; elapsed: {stopwatch.Elapsed}");
        await _messageAssertion.AssertAsync(message, redelivered);
    }
